    Find Flash Control Block offset

    @return int offset >=0 on success, -1 if an error occured.
    """
def find_fcb_offset(content: Any) -> object {
    try {
        index = content.index(b'FCB ');
        if (index > 4) {
            return (index - 4);
        }
        return -1;
    } except ValueError as exc {
        return -1;
    }
}

